# mBot OTA commissioning loader. Contains PRIVATE provisioning.
WIFI_SSID = "ENTER_WIFI_NAME"
WIFI_PASSWORD = ""
MQTT_BROKER = "192.168.0.10"
MQTT_PORT = 1883
MQTT_TOPIC_PREFIX = "mbot-studio"
OTA_DEVICE = "mbot2-rover"

"""Trusted-LAN application OTA core (no authentication); no import-time I/O or hardware access.

Uses only MicroPython 1.11 primitives. The caller supplies an existing
root directory and must call boot_selection once before running an application.
"""
try:
    import ujson as json
except ImportError:
    import json
try:
    import uhashlib as hashlib
except ImportError:
    import hashlib
try:
    import ubinascii as binascii
except ImportError:
    import binascii
import os
try:
    import ure as re
except ImportError:
    import re


def _hex(data):
    return binascii.hexlify(data).decode('ascii')


def _digest(data):
    return hashlib.sha256(data).digest()


def _ishex(value, length):
    if type(value) is not str or len(value) != length:
        return False
    try:
        # Native validation, no Python per-character loop.
        return _hex(binascii.unhexlify(value)) == value
    except (ValueError, TypeError):
        return False


def _integer(value, low, high):
    return type(value) is int and low <= value <= high


def _keys(value, names):
    return type(value) is dict and set(value) == set(names)


def _object(text):
    # Native duplicate-key semantics; no Python scanner or recursive validation.
    if type(text) not in (str, bytes) or len(text) > 8192:
        raise ValueError('json_size')
    result = json.loads(text)
    if type(result) is not dict:
        raise ValueError('object_required')
    return result


class OtaError(Exception):
    pass


class OtaEngine:
    def __init__(self, root, device, boot):
        if (type(root) is not str or not root or
                type(device) is not str or not 1 <= len(device) <= 48 or
                re.match('^[A-Za-z0-9_-]+$', device) is None or '\n' in device or
                not _ishex(boot, 32)):
            raise ValueError('provisioning')
        self.root = root.rstrip('/')
        self._last_request = None
        self._last_response = None
        self.device = device
        self.boot = boot
        self.next_seq = 1
        self.confirmed = None
        self.candidate = None
        self.trial = None
        self.receiving = None
        self.healthy = False
        self.selected = None
        self._generation = 0
        self._fault = False
        self._boot_selected = False
        self._load_metadata()

    def _path(self, slot):
        return self.root + '/app_' + slot + '.py'

    def _descriptor(self, value):
        return (value is None or (_keys(value, ('slot', 'sha256', 'size')) and
                value['slot'] in ('a', 'b') and _ishex(value['sha256'], 64) and
                _integer(value['size'], 1, 131072)))

    def _read_metadata(self, path):
        with open(path, 'r') as stream:
            text = stream.read(4097)
        if len(text) > 4096:
            raise ValueError('metadata')
        record = _object(text)
        if (not _keys(record, ('generation', 'body', 'sha256')) or
                not _integer(record['generation'], 1, 2147483647) or
                type(record['body']) is not str or not _ishex(record['sha256'], 64)):
            raise ValueError('metadata')
        expected = _hex(_digest(('mbot-ota-meta-v1\n' + self.device + '\n' +
                         str(record['generation']) + '\n' + record['body']).encode('utf-8')))
        if expected != record['sha256']:
            raise ValueError('metadata')
        state = _object(record['body'])
        if (not _keys(state, ('confirmed', 'candidate', 'trial')) or
                not self._descriptor(state['confirmed']) or not self._descriptor(state['candidate'])):
            raise ValueError('metadata')
        trial = state['trial']
        if trial is not None and (not _keys(trial, ('slot', 'sha256', 'size', 'attempted')) or
                type(trial['attempted']) is not bool or
                not self._descriptor(dict(slot=trial['slot'], sha256=trial['sha256'], size=trial['size'])) or
                state['candidate'] != dict(slot=trial['slot'], sha256=trial['sha256'], size=trial['size'])):
            raise ValueError('metadata')
        if state['confirmed'] and state['candidate'] and state['confirmed']['slot'] == state['candidate']['slot']:
            raise ValueError('metadata')
        return record['generation'], state

    def _load_metadata(self):
        records = []
        exists = False
        for index in (0, 1):
            path = self.root + '/meta' + str(index) + '.json'
            try:
                os.stat(path)
            except OSError as error:
                if error.args and error.args[0] == 2:
                    continue
                raise ValueError('metadata_unreadable')
            exists = True
            try:
                records.append(self._read_metadata(path))
            except (OSError, ValueError, TypeError, KeyError):
                pass
        if exists and not records:
            raise ValueError('metadata_corrupt')
        if records:
            if len(records) == 2 and records[0][0] == records[1][0] and records[0][1] != records[1][1]:
                raise ValueError('metadata_conflict')
            generation, state = max(records, key=lambda item: item[0])
            self._generation = generation
            self.confirmed = state['confirmed']
            self.candidate = state['candidate']
            self.trial = state['trial']

    def _save(self, confirmed, candidate, trial):
        if self._fault:
            raise OtaError('storage_fault')
        state = dict(confirmed=confirmed, candidate=candidate, trial=trial)
        generation = self._generation + 1
        body = json.dumps(state)
        # Corruption checksum only, NOT authentication or security.
        checksum = _hex(_digest(('mbot-ota-meta-v1\n' + self.device + '\n' +
                    str(generation) + '\n' + body).encode('utf-8')))
        text = json.dumps(dict(generation=generation, body=body, sha256=checksum))
        try:
            # Both records are synchronized before success or any execution.
            # A failed second write prohibits further mutations this boot.
            for index in (0, 1):
                path = self.root + '/meta' + str(index) + '.json'
                temporary = path + '.tmp'
                with open(temporary, 'w') as stream:
                    stream.write(text)
                if self._read_metadata(temporary) != (generation, state):
                    raise ValueError('readback')
                os.rename(temporary, path)
                if self._read_metadata(path) != (generation, state):
                    raise ValueError('readback')
        except (OSError, ValueError, TypeError):
            self._fault = True
            self.healthy = False
            raise OtaError('storage_fault')
        self._generation = generation
        self.confirmed = confirmed
        self.candidate = candidate
        self.trial = trial

    def _verify_file(self, descriptor):
        digest = hashlib.sha256()
        size = 0
        with open(self._path(descriptor['slot']), 'rb') as stream:
            while True:
                data = stream.read(1024)
                if not data:
                    break
                size += len(data)
                if size > descriptor['size']:
                    raise OtaError('size')
                digest.update(data)
        if size != descriptor['size']:
            raise OtaError('size')
        if _hex(digest.digest()) != descriptor['sha256']:
            raise OtaError('digest')

    def status(self):
        return dict(confirmed=dict(self.confirmed) if self.confirmed else None,
                    candidate=dict(self.candidate) if self.candidate else None,
                    trial=dict(self.trial) if self.trial else None,
                    receiving=dict(self.receiving) if self.receiving else None,
                    healthy=self.healthy,
                    selected=dict(self.selected) if self.selected else None,
                    next_seq=self.next_seq)

    def _envelope(self, seq, op, body):
        text = json.dumps(body)
        return dict(v=1, device=self.device, boot=self.boot, seq=seq, op=op,
                    body=text)

    def hello(self):
        body = self.status()
        body['protocol'] = 1
        body['loader'] = '1'
        return self._envelope(0, 'hello', body)

    def handle(self, request):
        seq = 0
        op = 'error'
        try:
            if type(request) in (str, bytes):
                if len(request) > 8192:
                    raise OtaError('envelope')
                request = _object(request)
            if not _keys(request, ('v', 'device', 'boot', 'seq', 'op', 'body')):
                raise OtaError('envelope')
            if (type(request['v']) is not int or request['v'] != 1 or
                    request['device'] != self.device or request['boot'] != self.boot or
                    not _integer(request['seq'], 1, 2147483647) or
                    type(request['op']) is not str or not 1 <= len(request['op']) <= 16 or
                    re.match('^[a-z]+$', request['op']) is None or '\n' in request['op'] or
                    type(request['body']) is not str or len(request['body'].encode('utf-8')) > 6144):
                raise OtaError('envelope')
            if len(json.dumps(request).encode('utf-8')) > 8192:
                raise OtaError('envelope')
            seq = request['seq']
            op = request['op']
            request_tuple = (request['v'], request['device'], request['boot'], seq, op, request['body'])
            if seq == self.next_seq - 1 and request_tuple == self._last_request:
                return dict(self._last_response)
            if seq != self.next_seq:
                raise OtaError('sequence')
        except (OtaError, ValueError, TypeError) as error:
            code = str(error) if isinstance(error, OtaError) else 'envelope'
            return self._envelope(seq, op, dict(ok=False, error=code))
        self.next_seq += 1
        try:
            try:
                body = _object(request['body'])
            except (ValueError, TypeError):
                raise OtaError('schema')
            result = self._dispatch(op, body)
            response = dict(ok=True, result=result)
        except OtaError as error:
            response = dict(ok=False, error=str(error))
        except (OSError, ValueError, TypeError):
            response = dict(ok=False, error='storage')
        envelope = self._envelope(seq, op, response)
        self._last_request = request_tuple
        self._last_response = envelope
        return dict(envelope)

    def boot_selection(self):
        if self._fault:
            return None
        if self._boot_selected:
            return dict(self.selected) if self.selected else None
        self._boot_selected = True
        self.healthy = False
        if self.trial:
            if self.trial['attempted']:
                self._save(self.confirmed, None, None)
            else:
                attempted = dict(self.trial)
                attempted['attempted'] = True
                # Never return executable trial until BOTH durable records say
                # attempted. Losing either record cannot grant a second trial.
                self._save(self.confirmed, self.candidate, attempted)
                try:
                    self._verify_file(self.candidate)
                    self.selected = dict(self.candidate)
                    return dict(self.selected)
                except (OSError, OtaError):
                    self._save(self.confirmed, None, None)
        if self.confirmed:
            try:
                self._verify_file(self.confirmed)
                self.selected = dict(self.confirmed)
            except (OSError, OtaError):
                self.selected = None
        return dict(self.selected) if self.selected else None

    def mark_healthy(self):
        if self._fault or not self._boot_selected or self.selected is None:
            return False
        self.healthy = True
        return True

    def _control(self, op, body):
        names = () if op == 'rollback' else ('sha256',)
        if not _keys(body, names) or (op != 'rollback' and not _ishex(body['sha256'], 64)):
            raise OtaError('schema')
        if self._fault:
            raise OtaError('storage_fault')
        if op == 'activate':
            if self.trial or self.receiving:
                raise OtaError('busy')
            if not self.candidate or self.candidate['sha256'] != body['sha256']:
                raise OtaError('candidate')
            self._verify_file(self.candidate)
            trial = dict(self.candidate)
            trial['attempted'] = False
            self._save(self.confirmed, self.candidate, trial)
            self.healthy = False
        elif op == 'confirm':
            if (not self.trial or not self.trial['attempted'] or not self.healthy or
                    self.selected != self.candidate or self.selected['sha256'] != body['sha256']):
                raise OtaError('not_healthy_trial')
            self._verify_file(self.selected)
            self._save(dict(self.selected), None, None)
        else:
            self._save(self.confirmed, None, None)
            self.receiving = None
            self.healthy = False
        result = self.status()
        if op in ('activate', 'rollback'):
            result['restart'] = True
        return result

    def _dispatch(self, op, body):
        if op in ('activate', 'confirm', 'rollback'):
            return self._control(op, body)
        if op == 'status':
            if not _keys(body, ()):
                raise OtaError('schema')
            return self.status()
        schemas = {'begin': ('transfer', 'size', 'sha256'),
                   'chunk': ('transfer', 'offset', 'data'),
                   'finish': ('transfer',), 'abort': ('transfer',)}
        if op not in schemas:
            raise OtaError('operation')
        if not _keys(body, schemas[op]):
            raise OtaError('schema')
        if not _ishex(body['transfer'], 32):
            raise OtaError('schema')
        if self._fault:
            raise OtaError('storage_fault')
        if op == 'begin':
            if not _integer(body['size'], 1, 131072) or not _ishex(body['sha256'], 64):
                raise OtaError('schema')
            if self.trial is not None or self.receiving is not None:
                raise OtaError('busy')
            slot = 'b' if self.confirmed and self.confirmed['slot'] == 'a' else 'a'
            self._save(self.confirmed, None, None)
            with open(self._path(slot), 'wb') as stream:
                stream.write(b'')
            self.receiving = dict(transfer=body['transfer'], size=body['size'],
                                  sha256=body['sha256'], slot=slot, offset=0)
            return self.status()
        transfer = self.receiving
        if transfer is None or body['transfer'] != transfer['transfer']:
            raise OtaError('transfer')
        if op == 'abort':
            self.receiving = None
            return self.status()
        if op == 'chunk':
            if (not _integer(body['offset'], 0, 131072) or type(body['data']) is not str or
                    not 2 <= len(body['data']) <= 2048 or len(body['data']) % 2 or
                    not _ishex(body['data'], len(body['data']))):
                raise OtaError('schema')
            data = binascii.unhexlify(body['data'])
            offset = body['offset']
            end = offset + len(data)
            if end > transfer['size'] or offset > transfer['offset']:
                raise OtaError('offset')
            if offset < transfer['offset']:
                if end > transfer['offset']:
                    raise OtaError('offset')
                with open(self._path(transfer['slot']), 'rb') as stream:
                    stream.seek(offset)
                    if stream.read(len(data)) != data:
                        raise OtaError('chunk_mismatch')
            else:
                with open(self._path(transfer['slot']), 'r+b') as stream:
                    stream.seek(offset)
                    if stream.write(data) != len(data):
                        raise OtaError('short_write')
                with open(self._path(transfer['slot']), 'rb') as stream:
                    stream.seek(offset)
                    if stream.read(len(data)) != data:
                        raise OtaError('readback')
                transfer['offset'] = end
            return self.status()
        descriptor = dict(slot=transfer['slot'], size=transfer['size'], sha256=transfer['sha256'])
        if transfer['offset'] != transfer['size']:
            raise OtaError('incomplete')
        self._verify_file(descriptor)
        self._save(self.confirmed, descriptor, None)
        self.receiving = None
        return self.status()


"""Commissioning-only cooperative OTA runtime; never a robot command bridge.

Provisioning constants are inlined by the USB bootstrap builder. This module
has no hardware side effects on import. Uploaded apps are trusted, not sandboxed.
"""
import hashlib
import binascii
import json
import os
from collections import namedtuple

# Named tuple offers immutable public identity, never engine/WDT handles.
AppContext = namedtuple("AppContext", ("device", "boot", "sha256", "loader", "protocol", "disarmed"))


def read_verified_source(root, selected, open_file=open, sha_factory=hashlib.sha256):
    """Hash the exact bounded bytes later executed, not a second file open."""
    slot, size, expected = selected.get("slot"), selected.get("size"), selected.get("sha256")
    if slot not in ("a", "b") or type(size) is not int or not 1 <= size <= 131072:
        raise ValueError("invalid_descriptor")
    if not isinstance(expected, str) or len(expected) != 64:
        raise ValueError("invalid_descriptor")
    try:
        if binascii.hexlify(binascii.unhexlify(expected)).decode() != expected:
            raise ValueError("invalid_descriptor")
    except (ValueError, TypeError):
        raise ValueError("invalid_descriptor")
    digest = sha_factory()
    parts, count = [], 0
    with open_file(root + "/app_" + slot + ".py", "rb") as source:
        while True:
            block = source.read(min(1024, size + 1 - count))
            if not block:
                break
            count += len(block)
            if count > size:
                raise ValueError("size_mismatch")
            digest.update(block)
            parts.append(block)
    if count != size or binascii.hexlify(digest.digest()).decode() != expected:
        raise ValueError("integrity_mismatch")
    return b"".join(parts)


def load_application(root, selected, reader=read_verified_source, executor=exec):
    """Caller MUST arm native watchdog before this function, including exec."""
    source = reader(root, selected)
    namespace = {"__name__": "ota_application"}
    executor(source, namespace)
    if type(namespace.get("OTA_APP_PROTOCOL")) is not int or namespace["OTA_APP_PROTOCOL"] != 1:
        raise ValueError("app_protocol")
    if not callable(namespace.get("ota_init")) or not callable(namespace.get("ota_step")):
        raise ValueError("app_interface")
    return namespace


class Mailbox:
    """Callback does no JSON, filesystem work or execution."""
    def __init__(self, topic, capacity=2, max_payload=8192):
        self.topic = topic
        self.capacity = capacity
        self.max_payload = max_payload
        self.items = []

    def put(self, topic, payload):
        if topic != self.topic or not isinstance(payload, bytes):
            return False
        if len(payload) > self.max_payload or len(self.items) >= self.capacity:
            return False
        self.items.append(payload)
        return True

    def pop(self):
        if self.items:
            return self.items.pop(0)
        return None


class MqttTransport:
    """Scheduled simple_mqtt/umqtt adapter, never a cloud fallback.

    Each service does at most one connect and one check_msg. Native vendor Wi-Fi,
    DNS and MQTT internals may block; native WDT is the final runtime bound,
    not evidence that these libraries or physical power-cut recovery work.
    Library packet allocation precedes callback limits (broker must be trusted).
    """
    def __init__(self, wifi, client_factory, mailbox, ssid, password, broker,
                 port, base_topic, client_id, ticks_diff, report):
        self.wifi, self.client_factory, self.mailbox = wifi, client_factory, mailbox
        self.ssid, self.password, self.broker, self.port = ssid, password, broker, port
        self.base_topic, self.client_id = base_topic, client_id
        self.ticks_diff, self.report = ticks_diff, report
        self.client, self.connected = None, False
        self.last_wifi, self.last_attempt, self.now = None, None, 0

    def drop(self):
        self.connected = False
        self.last_attempt = self.now
        if self.client:
            try:
                self.client.sock.close()
            except Exception:
                pass
        self.client = None

    def service(self, now):
        self.now = now
        try:
            if not self.wifi.is_connect():
                if self.client:
                    self.drop()
                if self.last_wifi is None or self.ticks_diff(now, self.last_wifi) >= 10000:
                    self.last_wifi = now
                    self.wifi.connect(self.ssid, self.password)
                return False
            if not self.connected:
                if self.last_attempt is not None and self.ticks_diff(now, self.last_attempt) < 2000:
                    return False
                self.last_attempt = now
                self.client = self.client_factory(self.client_id.encode(), self.broker,
                                                  port=self.port, keepalive=30)
                self.client.set_callback(self.mailbox.put)
                self.client.connect(clean_session=True)
                self.client.sock.settimeout(1)
                self.client.subscribe(self.mailbox.topic, qos=0)
                self.connected = True
                self.report("mqtt_connected")
            self.client.check_msg()
            return True
        except Exception:
            self.drop()
            self.report("network_retry")
            return False

    def publish(self, suffix, envelope):
        if not self.connected or suffix not in ("hello", "response"):
            return False
        try:
            # check_msg may restore blocking mode internally; restore our bound.
            self.client.sock.settimeout(1)
            self.client.publish((self.base_topic + "/" + suffix).encode(),
                                json.dumps(envelope).encode(), retain=False, qos=0)
            return True
        except Exception:
            self.drop()
            self.report("network_retry")
            return False


class Controller:
    """One service attempt and one app step per cycle; no callback execution."""
    def __init__(self, engine, transport, mailbox, root, identity,
                 watchdog_factory, reset, prepare_app, ticks_diff, report):
        self.engine, self.transport, self.mailbox = engine, transport, mailbox
        self.root, self.context = root, identity
        self.watchdog_factory, self.reset = watchdog_factory, reset
        self.prepare_app, self.ticks_diff, self.report = prepare_app, ticks_diff, report
        self.started, self.healthy, self.failed = False, False, False
        self.watchdog, self.app, self.last_hello = None, None, None
        self.pending_response = None

    def fail(self, code):
        # Trial exceptions reset for persisted rollback. Confirmed-app exceptions
        # stay in recovery so a replacement can arrive instead of a reboot loop.
        # Native hangs still rely on WDT; confirmed native-hang loops are not solved.
        self.app = None
        self.healthy = False
        self.engine.healthy = False
        self.report(code)
        if self.engine.trial and self.engine.trial.get("attempted"):
            self.failed = True
            self.reset()

    def start(self):
        if self.started:
            raise RuntimeError("already_started")
        self.started = True
        try:
            selected = self.engine.boot_selection()
            try:
                self.watchdog = self.watchdog_factory(timeout=8000)
                if not callable(getattr(self.watchdog, "feed", None)):
                    raise ValueError("watchdog_unavailable")
            except Exception:
                self.watchdog = None
                self.report("watchdog_unavailable_recovery")
                return
            if selected:
                self.context = AppContext(self.context["device"], self.context["boot"],
                                          selected["sha256"], "1", 1, True)
                self.app = self.prepare_app(self.root, selected)
                self.app["ota_init"](self.context)
        except Exception:
            self.fail("app_start_failed")

    def cycle(self, now):
        if self.failed:
            return
        try:
            self._cycle(now)
        except Exception:
            self.fail("runtime_failed")

    def _cycle(self, now):
        connected = self.transport.service(now)
        if self.app:
            self.app["ota_step"](self.context)
            if not self.healthy:
                if self.engine.mark_healthy() is False:
                    raise ValueError("health_refused")
                self.healthy = True
        if connected:
            if self.pending_response is None:
                payload = self.mailbox.pop()
                if payload is not None:
                    # Engine owns bounded native parsing in the main loop;
                    # callback only queues bytes.
                    self.pending_response = self.engine.handle(payload)
            if self.pending_response is not None:
                response = self.pending_response
                if self.transport.publish("response", response):
                    self.pending_response = None
                    body = json.loads(response["body"])
                    if (response.get("op") in ("activate", "rollback")
                            and body.get("ok") is True
                            and body.get("result", {}).get("restart") is True):
                        self.failed = True
                        self.reset()
                        return
        if connected and (self.last_hello is None or self.ticks_diff(now, self.last_hello) >= 5000):
            if self.transport.publish("hello", self.engine.hello()):
                self.last_hello = now
        if self.watchdog:
            self.watchdog.feed()


def best_effort_stop(stop_wheels, stop_dc, report):
    """Two independent stop-only attempts; NOT proof of actuator safety."""
    for stop, error in ((stop_wheels, "wheel_stop_failed"), (stop_dc, "dc_stop_failed")):
        try:
            stop()
        except Exception:
            report(error)


def _stop_wheels():
    import mbot2
    mbot2.EM_stop()


def _stop_dc():
    import mbot2
    mbot2.starter_shield.dc_motor_stop()


def report_status(code, display):
    print("OTA:", code)
    try:
        display("OTA: " + code)
    except Exception:
        pass


def _native_report(code):
    import cyberpi
    report_status(code, lambda text: cyberpi.display.show_label(text, 12, "center", index=0))


def _native_adapters():
    # Only main reaches native imports; no tests emulate cyberpi or import apps
    # with pretend hardware. Native call bounds still require commissioning.
    import cyberpi
    import machine
    import time
    import os
    try:
        from simple_mqtt import MQTTClient
    except ImportError:
        from umqtt.simple import MQTTClient
    try:
        import socket
        socket.setdefaulttimeout(2)
    except (ImportError, AttributeError):
        # MicroPython variants lack the global timeout setter. Native WDT
        # bounds connect/DNS/check_msg, not just candidate code, when available.
        pass
    return {"wifi": cyberpi.wifi, "mqtt_factory": MQTTClient,
            "engine_factory": OtaEngine, "transport_factory": MqttTransport,
            "watchdog_factory": getattr(machine, "WDT", None), "reset": machine.reset,
            "urandom": os.urandom, "ticks_ms": time.ticks_ms,
            "ticks_diff": time.ticks_diff, "sleep_ms": time.sleep_ms, "report": _native_report}


def ensure_root(root):
    """Create only an absent directory; preserve existing files and metadata."""
    try:
        mode = os.stat(root)[0]
    except OSError as error:
        if not error.args or error.args[0] != 2:
            raise
        os.mkdir(root)
        mode = os.stat(root)[0]
    if mode & 0xf000 != 0x4000:
        raise ValueError("ota_root_not_directory")


def main(adapters=None, cycles=None):
    """Native entrypoint; optional injected adapters/cycle bound are host-only.

    Bootstrap constants MUST be supplied inline; no credentials or broker
    defaults, provisioning imports, remote config, or legacy subscriptions.
    The only infinite loop belongs to the loader, never to the diagnostic app.
    """
    if adapters is None:
        _native_report("bootstrap_starting")
        best_effort_stop(_stop_wheels, _stop_dc, _native_report)
        try:
            adapters = _native_adapters()
        except Exception:
            _native_report("native_adapters_unavailable")
            return None
    else:
        best_effort_stop(adapters["stop_wheels"], adapters["stop_dc"], adapters["report"])
    report = adapters["report"]
    try:
        nonce = adapters["urandom"](16)
        if not isinstance(nonce, bytes) or len(nonce) != 16:
            raise ValueError("boot_entropy")
        boot = binascii.hexlify(nonce).decode()
        root = "/flash/mbot_ota"
        adapters.get("ensure_root", ensure_root)(root)
        engine = adapters["engine_factory"](root, OTA_DEVICE, boot)
        base = MQTT_TOPIC_PREFIX + "/ota/" + OTA_DEVICE
        mailbox = Mailbox((base + "/request").encode())
        transport = adapters["transport_factory"](
            adapters["wifi"], adapters["mqtt_factory"], mailbox, WIFI_SSID,
            WIFI_PASSWORD, MQTT_BROKER, MQTT_PORT, base, OTA_DEVICE + "-" + boot,
            adapters["ticks_diff"], report)
        controller = Controller(engine, transport, mailbox, root,
                                {"device": OTA_DEVICE, "boot": boot},
                                adapters["watchdog_factory"], adapters["reset"],
                                load_application, adapters["ticks_diff"], report)
        controller.start()
        report("application_loaded" if controller.app else "recovery_waiting_wifi")
    except Exception:
        # Invalid provisioning, entropy or corrupt metadata: never execute app,
        # never silently initialize/erase metadata, never leak exception text.
        report("bootstrap_failed")
        return None
    count = 0
    while cycles is None or count < cycles:
        controller.cycle(adapters["ticks_ms"]())
        adapters["sleep_ms"](20)
        if cycles is not None:
            count += 1
    return controller


main()
